  "cfc.rule": "Regel (Wettkampfordnung 2026, Anhang 2): Jeder Läufer bringt seinem Verein die Summe seiner 5 besten offiziellen CN-Scores des Jahres im Fuß-OL (Wald und Sprint) plus seiner 5 besten im MTB-O oder Ski-O; die Punkte einer Frau werden mit 1,4 multipliziert. Berechnung von Ozimut, nicht offiziell: Alle gewerteten Läufer zählen (die Lizenzart ist nicht bekannt), und ein Läufer, der im Lauf des Jahres den Verein gewechselt hat, zählt für den Verein seines letzten Laufs. * Der Pokal wurde von 2023 bis 2025 nicht vergeben.",
