  "prov.refusedOnly": "für Robots gesperrte Quellen",
  "prov.def": "Es werden nur die Läufe der letzten 60 Tage gezeigt. Gelesene Quellen: liveresultat, WinSplits, Helga, Orientation Data und die Website des Veranstalters (Ergebnis- und Zwischenzeitdateien); Websites, die Robots ablehnen, werden nicht gelesen. Jeder Lauf wird 3 Tage lang bei jeder stündlichen Abfrage angesehen, danach einmal täglich bis zum 14. Tag. Die Scores und Indizes sind vorläufig: Die später vom Verband veröffentlichten können abweichen.",
