  "prov.scoreDef": "Scores wie auf dem Rest der Website berechnet, aus den im CN gefundenen Läufern: Ein nicht gefundener Läufer zählt nicht im Bahnwert, was ihn etwas von der endgültigen Berechnung abweichen lassen kann.",
  "spl.title": "Zwischenzeiten",
  "spl.lede": "Die von den Veranstaltern veröffentlichten Zwischenzeiten, Bahn für Bahn: die Tabelle der Zeiten und des Zeitverlusts, die Abstände, die Durchgänge, die tückischen Teilstrecken, das Profil, der Direktvergleich, die Gruppen, die Selbstständigkeit (wer wem gefolgt ist), die Gleichmäßigkeit und eine Bilanz pro Läufer.",
