  "spl.finish": "Ziel",
  "ra.lede": "Die letzten Läufe mit veröffentlichten Zwischenzeiten und die Live-Läufe, die welche liefern: Wähle einen aus, um seine Zeiten Bahn für Bahn zu analysieren — Zeitverlust, Abstände, Durchgänge, Teilstrecken, Gruppen, Gleichmäßigkeit.",
