  "ra.def": "Ein Lauf steht hier 60 Tage lang, sobald eine seiner Bahnen vom Veranstalter veröffentlichte Zwischenzeiten hat (WinSplits, Helga, liveresultat, seine Website oder sein Upload). Die Spalte „Ergebnisse“ führt zur Seite des Laufs.",
