  "spl.grp.none": "Keine Startzeiten für diese Bahn: Gruppen können nicht erkannt werden (WinSplits, liveresultat und IOF-XML-Dateien liefern sie).",
  "spl.grp.legs": "Teilstrecken in der Gruppe",
  "spl.grp.pack": "Anteil in der Gruppe",
  "spl.grp.front": "Vorne",
  "spl.grp.behind": "Hinten",
  "spl.grp.follow": "Anteil hinten",
  "spl.grp.gain": "Hinten gewonnen",
  "spl.grp.with": "Mit",
  "spl.grp.map": "Gruppenkarte",
  "spl.grp.map.hint": "Pro Teilstrecke die Zahl der Läufer in Begleitung; grün: der Läufer stempelt als Erster, rot: dahinter. Fahre über eine Zelle, um zu sehen, mit wem",
  "spl.grp.def": "Anteil in der Gruppe, Anteil hinten: die Zeit der in der Gruppe bzw. hinter einem anderen Läufer gelaufenen Teilstrecken im Verhältnis zur Laufzeit vom 1. bis zum letzten Posten (Start und Ziel, wo die Läufer getrennt oder alle zusammen sind, zählen nicht). Hinten gewonnen: auf den hinten gelaufenen Teilstrecken die gegenüber dem üblichen Tempo des Läufers gewonnene Zeit (negativ: verloren). Die Posten unter „Mit“ sind die, zwischen denen die Läufer zusammen gelaufen sind.",
  "spl.sum": "Bilanz pro Läufer",
  "spl.sum.hint": "Klicke auf eine Spaltenüberschrift zum Sortieren",
  "spl.won": "Gewonnene Teilstrecken",
  "spl.avgRank": "Mittlerer Rang",
  "spl.lostPct": "Verlustanteil",
  "spl.pace": "Übliches Tempo",
  "spl.reg": "Unregelmäßigkeit",
  "spl.kmPace": "Min/km",
  "spl.sum.def": "Gewonnene Teilstrecken: die Bestzeiten. Mittlerer Rang: auf den Teilstrecken. Verlustanteil: der Zeitverlust im Verhältnis zur Laufzeit. Übliches Tempo: der Abstand zur Bestzeit auf den fehlerfrei gelaufenen Teilstrecken (die Zeit des Läufers im Verhältnis zur Summe der Bestzeiten). Unregelmäßigkeit: die Streuung der Abstände zur Bestzeit (Variationskoeffizient); je niedriger, desto gleichmäßiger der Lauf. Gewonnene Duelle: die Läufer der Bahn, die auf mehr Teilstrecken geschlagen wurden, als sie gewonnen haben.",
  "prov.seeSplits": "Anzeigen",
  "spl.def": "Zeitverlust: auf jeder Teilstrecke der Abstand zwischen der Zeit des Läufers und seiner „idealen“ Zeit: die Referenzzeit der Teilstrecke (der Mittelwert des schnellsten Sechstels ohne den Sieger; bei weniger als 12 Zeiten der Mittelwert der zwei besten, bei weniger als 5 die beste) mal sein übliches Tempo, also seine Zeit auf den fehlerfrei gelaufenen Teilstrecken im Verhältnis zu deren Referenzzeiten — eine lange Teilstrecke zählt dabei mehr als eine kurze. So berechnen MeOS und WinSplits den Zeitverlust, an denen sich die meisten Ansichten dieser Seite orientieren.",
  "spl.tab.clock": "Durchgänge",
  "spl.tab.follow": "Selbstständigkeit",
  "spl.tab.regular": "Gleichmäßigkeit",
  "spl.start": "Start",
  "spl.startAbbr": "S",
  "spl.finishAbbr": "Z",
  "spl.table.marks": "Oranger Rahmen: eine Zeit, die die Prüfungen oben für zweifelhaft halten (fahre über die Zelle).",
  "spl.table.followed": "Farbiger Strich links: eine Teilstrecke, die hinter einem anderen Läufer gelaufen wurde (siehe „Selbstständigkeit“).",
  "spl.clk.all": "Alle Läufer",
  "spl.clk.sel": "Nur verglichene Läufer",
  "spl.clk.title": "Grafik der Durchgänge",
  "spl.clk.hint": "Jede Linie: ein Läufer, Posten für Posten, zur Uhrzeit seines Durchgangs. Linien, die sich treffen: Läufer zusammen; eine steilere Linie: ein Läufer, der andere einholt. Mausrad zum Zoomen; wähle die farbigen Läufer unter der Grafik",
  "spl.clk.def": "Die Uhrzeiten sind die der Durchgänge: Startzeit plus kumulierte Zeit an jedem Posten. Gezeichnet werden nur die Läufer mit bekannter Startzeit ({n} von {of}).",
  "spl.clk.none": "Keine Startzeiten für diese Bahn: Die Durchgänge können zeitlich nicht eingeordnet werden (WinSplits, liveresultat und IOF-XML-Dateien liefern sie).",
  "spl.fol.thr": "Zusammen bei weniger als",
  "spl.fol.t1": "Abstand in Sekunden, bis zu dem zwei Läufer ganz zusammen sind",
  "spl.fol.t2": "Abstand in Sekunden, ab dem sie nicht mehr zusammen sind",
  "spl.fol.t1u": "s, dann immer weniger bis",
  "spl.fol.t2u": "s",
  "spl.fol.title": "Selbstständigkeit: wer wem gefolgt ist",
  "spl.fol.hint": "Auf jeder Teilstrecke zwei Läufer der Bahn, die den gleichen Posten mit weniger als {t2} s Abstand verlassen haben: zusammen, wo sie weniger als {t1} s trennen, immer weniger bis {t2} s. Der Zweite folgt dem Ersten. Klicke auf eine Spaltenüberschrift zum Sortieren",
  "spl.fol.def": "Mitläufer-Index: die hinter einem anderen Läufer gelaufene Zeit minus die vorne gelaufene, im Verhältnis zur Zeit der gezählten Teilstrecken (positiv: eher Mitläufer, negativ: eher Zugpferd). Zwischen zwei Posten wird angenommen, dass jeder gleichmäßig läuft: Es ist eine Schätzung, und ein zeitlich naher Läufer wird nicht unbedingt verfolgt (er kann eine andere Route gewählt haben). Es braucht die Startzeiten; es zählen nur Teilstrecken, deren beide Zeiten bekannt sind. Eine Teilstrecke gilt als „hinten“ oder „vorne“, wenn das für mehr als die Hälfte ihrer Zeit zutrifft.",
  "spl.fol.none": "Keine Startzeiten für diese Bahn (oder nur ein Läufer): Man kann nicht wissen, wer mit wem gelaufen ist.",
  "spl.fol.index": "Mitläufer-Index",
  "spl.fol.index.hint": "Zeit hinten minus Zeit vorne, als Anteil der Laufzeit",
  "spl.fol.behindT": "Hinten",
  "spl.fol.aheadT": "Vorne",
  "spl.fol.legsBehind": "Teilstrecken hinten",
  "spl.fol.legsAhead": "Teilstrecken vorne",
  "spl.fol.main": "Hauptbegleiter",
  "spl.fol.wasBehind": "hinten {t}",
  "spl.fol.wasAhead": "vorne {t}",
  "spl.fol.cell": "Hinter {who} gelaufen",
  "spl.reg.chart": "Streuung auf jeder Teilstrecke",
  "spl.reg.chartHint": "Wie weit die Läufer auf dieser Teilstrecke von ihrem eigenen Niveau abgewichen sind, in Punkten: Die höchsten Balken sind die Teilstrecken, auf denen jeder anders als sonst gelaufen ist",
  "spl.reg.title": "Gleichmäßigkeit der Läufer",
  "spl.reg.hint": "Über {n} der {of} Läufer: die, die mit allen Zwischenzeiten ins Ziel gekommen sind. Klicke auf eine Spaltenüberschrift zum Sortieren",
  "spl.reg.def": "Leistungsindex einer Teilstrecke: ihre Referenzzeit (der Mittelwert des besten Viertels der Zeiten) geteilt durch die Zeit des Läufers; 100 %: so schnell wie die Besten, 50 %: doppelt so langsam. Unregelmäßigkeit: die Standardabweichung dieser Indizes, jede Teilstrecke gewichtet mit ihrer Referenzzeit (eine lange Teilstrecke sagt mehr als eine kurze), im Verhältnis zum mittleren Index des Läufers (10 Punkte Abweichung wiegen mehr für jemanden, der mit 40 % läuft, als mit 90 %); je niedriger, desto gleichmäßiger der Lauf. Die Streuung einer Teilstrecke ist die der Indizes der Läufer im Verhältnis zu ihrem eigenen Mittelwert: Ohne das Niveau des Einzelnen zeigt sie, wo alle geschwankt haben.",
  "spl.reg.none": "Niemand hat diese Bahn mit allen Zwischenzeiten beendet: Die Gleichmäßigkeit kann nicht berechnet werden.",
  "spl.reg.spread": "Streuung",
  "spl.reg.pts": "Punkte",
  "spl.reg.ref": "Referenzzeit",
  "spl.reg.legMean": "Mittlerer relativer Index",
  "spl.reg.mean": "Mittlerer Index",
  "spl.reg.sd": "Unregelmäßigkeit",
  "spl.reg.bestLeg": "Beste Teilstrecke",
  "spl.reg.worstLeg": "Schwächste Teilstrecke",
