  "lv.score.hint": "Der Score, den diese Zeit wert ist, geschätzt aus den Läufern im Ziel der Kategorie oder Bahn: der Bahnwert geteilt durch die Zeit — offiziell: der Mittelwert von CN × Zeit der ⌈2N/3⌉ Schnellsten mit CN; Ozimut: der Mittelwert von üblichem Niveau × Zeit der Schnellsten mit Niveau (90 % des Feldes im Wald, zwei Drittel im Sprint, 75 % bei MTB-O und Ski-O). Neben dem Score die Abweichung {cnTo} des Läufers: grün besser als sein Niveau, rot schlechter.",
