  "dep.title": "Ergebnisse hochladen",
  "dep.lede": "Lade die aus deiner Zeitnahme-Software exportierte Ergebnisdatei. Sie wird hier in deinem Browser gelesen: Nichts wird gesendet. Du siehst sofort die Ergebnisse und alle Analysen der Zwischenzeiten und entscheidest dann, ob du sie auf Ozimut veröffentlichen möchtest.",
