  "os.help.title": "Unterstützte Formate",
  "os.help.best": "Am besten:",
  "os.help.best.text": "der IOF-XML-3.0-Export „StartList“ aus deiner Software (OE, MeOS, OS…); alles ist enthalten, eindeutig.",
  "os.help.csv": "CSV:",
  "os.help.csv.text": "eine Kopfzeile, dann ein Läufer pro Zeile. Erkannte Spalten, in beliebiger Reihenfolge: Start (oder Heure, Départ), Surname (oder Nom), First name (oder Prénom; oder der ganze Name in einer Spalte), Club, Course (oder Circuit), Class (oder Catégorie). Uhrzeit und Name genügen; ohne Spalte Course wird die Liste nach Kategorie geordnet. Trennzeichen Semikolon, Komma oder Tabulator. Beispiel:",
  "os.help.csv.example": "Course;Start;Surname;First name;Club;Class\nViolett lang;10:00;DUPONT;Jeanne;0109;D21\nViolett lang;10:02;MARTIN;Paul;7707;H35\nOrange;10:01;LEROY;Léa;0111;D16",
  "os.help.csv.notes": "Uhrzeiten als 10:02 oder 10h02 (oder 10:02:30). Club: seine Nummer, eventuell gefolgt vom Namen, hilft, die Läufer zu erkennen. CSV-Exporte von OE und MeOS werden ebenfalls gelesen.",
  "os.help.sheet": "Google Sheets:",
  "os.help.sheet.text": "Füge den Link der Tabelle ein, freigegeben für „Jeder, der über den Link verfügt“. Sie kann dem CSV-Aufbau oben folgen oder ein Raster sein: eine Zeile mit den Namen der Bahnen, dann für jede Bahn eine Kopfzeile Start / Name / Club, ein Start pro Zeile:",
  "os.help.sheet.example": "         Violett lang         Orange\nStart    Name          Club   Name         Club\n10:00    Jeanne DUPONT 0109   Léa LEROY    0111\n10:02    Paul MARTIN   7707\nEine Start-Spalte pro Bahn geht auch.",
  "os.help.else": "Sonst:",
  "os.help.else.text": "die HTML-Seiten deiner Software oder die PDFs von OE und MeOS. Eine Excel-Tabelle speichere als CSV.",
