  "an.perso.title": "Einzelanalyse",
  "an.perso.lede": "Dein GPS-Track auf deiner Karte, für ein Training oder jeden Lauf: Karte und Track werden in deinem Browser gelesen, nichts wird gesendet. Die Bahn wird von der Karte gelesen und der Track automatisch darauf ausgerichtet; danach wird der Lauf auf der Karte abgespielt.",
  "an.lede": "Dein GPS-Track auf deiner Karte, für einen Lauf aus „Ergebnisse“: Karte und Track werden in deinem Browser gelesen, nichts wird gesendet. Die Bahn wird von der Karte gelesen und der Track automatisch darauf ausgerichtet; die veröffentlichten Zwischenzeiten, falls vorhanden, verfeinern die Kalibrierung; danach wird der Lauf auf der Karte abgespielt.",
