  "sh.legs.rule": "Zeitverlust: die Teilstreckenzeit minus die Zeit beim üblichen Tempo des Läufers (Bestzeit × Median seiner Verhältnisse zu dieser Bestzeit). Ein Fehler, in Rot: mindestens 20 % der Teilstreckenzeit und mindestens 10 s.",
