  "an.drop.hint": "die Karte (Bild, PDF, KMZ, OCAD oder Mapper) und den Track (GPX, TCX oder FIT); falls vorhanden, die Georeferenzierungsdatei der Karte (.jgw/.pgw/.wld + .prj, KML) und die Bahndatei (IOF XML aus Purple Pen, OCAD oder Condes)",
