  "an.formats.trace": "Der Track: die Datei deiner Uhr oder App — FIT (Garmin, Coros, Suunto… mit Herzfrequenz, Kadenz und Höhe), GPX oder TCX.",
  "an.formats.geo": "Die Georeferenzierung: Mit einer georeferenzierten Karte (OCAD, OOM: Export mit World File oder als KMZ) wird der Track platziert, ohne etwas auf der Karte zu lesen. Ohne .prj wird das System erraten (Lambert 93, UTM).",
  "an.formats.iof": "Die Bahn: Das IOF XML aus Purple Pen (Datei › IOF-XML-Datei erstellen) oder aus OCAD/Condes liefert die Posten, ihre Reihenfolge und ihre Codes und, wenn die Karte georeferenziert ist, ihre Koordinaten.",
  "an.formats.ocad": "OCAD-Dateien (.ocd) und OpenOrienteering-Mapper-Dateien (.omap, .xmap) werden gelesen: Allein abgelegt, sind sie die Karte, hier gezeichnet und über ihre Georeferenzierung platziert; zusammen mit einem Bild der Karte dienen sie den berechneten Routen.",
