  "ia.data": "Die Daten",
  "ia.lede": "Stell eine Frage zu den Ranglisten, Ergebnissen oder Vereinen: Eine KI schreibt die Abfrage, dein Browser führt sie auf den Daten der Website aus und macht daraus eine Tabelle oder ein Diagramm.",
  "ia.placeholder": "Zum Beispiel: mein Ozimut-Index im Wald Monat für Monat seit 2024",
  "ia.model.tip": "Das Modell, das die Abfrage schreibt",
  "ia.ask": "Fragen",
  "ia.note": "Kostenlos, im Rahmen von etwa hundert Fragen pro Tag für die ganze Website (15 pro Person und Tag; ohne Limit mit deinem eigenen Schlüssel, siehe unten). Die KI sieht die Daten nicht: Sie schreibt eine Abfrage, die dein Browser ausführt. Sie kann sich irren: Die gewählte Interpretation und die Abfrage stehen unter jeder Antwort.",
  "ia.byok.summary": "Dein eigener API-Schlüssel: Claude, ChatGPT, Gemini oder OpenRouter",
  "ia.byok.intro": "Ein leistungsfähigeres Modell, auf deine Kosten: Dein Browser ruft es direkt mit deinem Schlüssel auf.",
