  "ia.err.generic": "Fehler {status}",
  "byok.note.openrouter": "Ein einziger Schlüssel für die meisten Modelle (Claude, GPT, Gemini, Llama…), ein Ausgabenlimit pro Schlüssel. Die kostenlosen Modelle sind auf 50 Anfragen pro Tag (1.000 nach dem Kauf von 10 Credits) und 20 pro Minute begrenzt — eine Frage ist eine Anfrage, zwei, wenn die Abfrage korrigiert wird —; manche ihrer Anbieter können die Fragen verwenden: Sieh dir die Datenschutzeinstellungen deines OpenRouter-Kontos an.",
  "byok.note.anthropic": "Die Claude-Modelle. Ein Workspace-Schlüssel mit Ausgabenlimit wird empfohlen.",
