  "rh.title": "Staffeln",
  "rh.lede": "Die Geschichte der beiden großen französischen Vereinsstaffeln: der Championnat de France des Clubs (CFC) seit 1999 und das Critérium National des Équipes (CNE) seit 2006 — vollständige Ranglisten, Erfolgsbilanz der Vereine, Austragungen.",
  "rh.none": "Die Geschichte der Staffeln ist nicht verfügbar.",
  "rh.sources": "Ranglisten aus den Archiven zusammengetragen: LIFCO, die frühere Website der FFCO (archives.ffcorientation.fr), die frühere Website des CO Mulhouse, der Newsletter des NOSE „ECO NOSE n°19“, die Dateien der Veranstalter und O'Live. CFC 1999-2003: nur der Sieger bekannt; 2004-2005: Auszüge; CNE 2015: einige Plätze; 2019: ein Auszug. Ein Fehler, eine fehlende Datei? Schreib uns.",
