  "hub.welcome": "Willkommen bei Ozimut",
  "hub.hello": "Hallo {name}",
  "hub.lede": "Wähle ein Modul. Das Ozimut-Logo oben links bringt dich jederzeit hierher zurück, um zu wechseln.",
  "hub.lede.short": "Wähle ein Modul",
  "hub.arena.text": "Alle Wettkämpfe an einem Ort: die kommenden mit ihren Infos und Startlisten, die laufenden live, und die Ergebnisse der letzten zwei Monate mit der Analyse der Zwischenzeiten.",
  "hub.stats.text": "Die nationale Rangliste und der Ozimut-Index, die Seite jedes Läufers, die gewerteten Läufe, die Vereine, die Staffeln und Statistiken über den gesamten französischen OL.",
  "hub.coach.text": "Spiel deinen Lauf mit deinem GPS-Track auf deiner Karte nach, vergleiche ihn mit denen der anderen, wiederhole die Postenbeschreibungen, trainiere dein Kartenlesen und berechne deine MAG.",
  "hub.coach.text.lim": "Spiel deinen Lauf mit deinem GPS-Track auf deiner Karte nach, vergleiche ihn mit denen der anderen, trainiere dein Kartenlesen und berechne deine MAG.",
  "hub.orga.text": "Für Veranstalter: Ergebnisse und Startzeiten veröffentlichen, live aus MeOS übertragen, die Bahnen legen und die Gruppenanalyse ihrer Läufer vorbereiten.",
