  "cd.source": "Symbole und Texte: Purple Pen, nach der internationalen Spezifikation für Postenbeschreibungen der IOF. Kartenzeichnungen: Ozimut, schematisch und nicht maßstabsgetreu, in den Farben und Symbolen der Normen ISOM 2017-2 und ISSprOM 2019-2.",
