  "tour.ov.menu": "Überblick",
  "tour.lvl.free": "Kostenlos für alle",
  "tour.method.long": "Dein Niveau über die Jahre",
  "tour.method.long.1.b": "Fünfzehn Saisons, eine einzige Regel.",
  "tour.method.long.1": "Der Ozimut-Index wird seit 2010 mit denselben Regeln neu berechnet, Wald, Sprint, MTB-O und Ski-O jeweils getrennt: Deine Kurve lässt sich von Anfang bis Ende lesen, ohne Bruch an dem Tag, an dem sich eine offizielle Regel ändert.",
  "tour.method.long.2.b": "Eine Skala, Monat für Monat.",
  "tour.method.long.2": "Jeden Monat wird der Index neu skaliert, damit die besten 20 % des Landes im Schnitt bei 5.600 bleiben, ohne Sprung beim Saisonwechsel: Ein Index von 2014 ist mit dem heutigen vergleichbar.",
  "tour.method.long.3.b": "Jeder Lauf ein für alle Mal bewertet.",
  "tour.method.long.3": "Der Score eines Laufs ändert sich nach seiner Veröffentlichung nicht mehr: Dein Verlauf bleibt, wie er ist, und deine Entwicklung lässt sich mit der deiner Altersklasse vergleichen.",
  "tour.multi.eyebrow": "Gruppenanalyse",
  "tour.multi.title": "Alle Tracks auf derselben Karte",
  "tour.multi.lede": "Der Veranstalter bereitet Karte und Bahn vor; jeder fügt seinen Track hinzu. Massenstart oder ab einem Posten, die Routen nebeneinander, die Varianten gruppiert, die Abstände Posten für Posten und das Duell: So lässt sich ein Vereinstraining wie ein Wettkampf nachbesprechen.",
  "tour.cap.multi.b": "Die Wiedergabe:",
  "tour.cap.multi": "jeder Läufer auf derselben Karte, im Massenstart, sein Tempo unter der Karte.",
  "tour.cap.multi-gaps.b": "Die Abstände:",
  "tour.cap.multi-gaps": "der Rückstand jedes Läufers auf den Besten, Posten für Posten; ein Klick auf einen Punkt setzt die Wiedergabe an diesen Durchgang.",
  "hub.orga.register": "Konto erstellen, um es zu öffnen",
  "arena.back": "Wettkämpfe",
