  "nav.mapkey": "Kartensymbole",
  "ms.title": "Kartensymbole",
  "ms.lede": "Die Symbole von OL-Karten, wie sie eine Kartenlegende zeigt: die Waldkarte und die Sprintkarte, jede in ihrem Tab, Gruppe für Gruppe – also Farbe für Farbe –, mit Nummer, Name und Bedeutung.",
  "ms.search.ph": "ein Name, ein Wort, eine Nummer",
  "ms.practice.off": "Nein",
  "ms.practice.names": "Namen ausblenden",
  "ms.practice.pics": "Zeichnungen ausblenden",
  "ms.practice.hint.names": "Die Namen sind ausgeblendet: Was bedeutet jede Zeichnung? Tippe darauf, um ihren Namen zu sehen, ein zweites Mal, um ihn wieder auszublenden.",
  "ms.practice.hint.pics": "Die Zeichnungen sind ausgeblendet: Wie sieht jedes Symbol aus? Tippe auf seinen Namen, um die Zeichnung zu sehen, ein zweites Mal, um sie wieder auszublenden.",
  "ms.colours": "Was die Farben sagen",
  "ms.colours.hint": "Die Farbe eines Symbols verrät schon, worum es geht.",
  "ms.c.brown": "Braun:",
  "ms.c.brown.say": "das Relief: Höhenlinien, Kuppen, Erosionsrinnen.",
  "ms.c.black": "Schwarz:",
