  "ms.c.paper.say": "Wald, in dem man normal laufen kann.",
  "ms.c.green": "Grün:",
  "ms.c.green.say": "Vegetation, die bremst – je dunkler das Grün, desto mehr.",
  "ms.c.purple": "Violett:",
