  "ms.forbidden": "verboten",
  "ms.source": "Nach ISOM 2017-2, der internationalen Spezifikation für OL-Karten der IOF: Nummern, Namen, Maße und Farben. Zeichnungen von Ozimut, im Maßstab der gedruckten Karte (die Bahnsymbole kleiner). Sprintkarten (ISSprOM 2019-2) haben eigene, ähnliche Symbole.",
